#!/bin/bash
# Re-render the share images from og/*.html with headless Chrome:
#   public/og.png               2400x1260  link previews (Open Graph / X)
#   public/share-instagram.png  1080x1350  Instagram feed (4:5)
#   + the -yue variants (generated by i18n/build.mjs)
set -e
cd "$(dirname "$0")"
CHROME="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
render() { # html out width height scale
  "$CHROME" --headless=new --disable-gpu --hide-scrollbars --force-device-scale-factor="$5" \
    --window-size="$3,$4" --virtual-time-budget=3000 --allow-file-access-from-files \
    --screenshot="$PWD/../public/$2" "file://$PWD/$1" >/dev/null 2>&1
  echo "wrote public/$2"
}
render card.html          og.png              1200 630  2
render card-portrait.html share-instagram.png 1080 1350 1
for code in zh-hk; do
  render card-$code.html          og-$code.png              1200 630  2
  render card-portrait-$code.html share-instagram-$code.png 1080 1350 1
done
